class Node:
    def __init__(self, val):
        self.val, self.left, self.right = val, None, None

def serialize(root):
    parts = []
    def dfs(node):
        if not node:
            parts.append("#")
            return
        parts.append(str(node.val))
        dfs(node.left)
        dfs(node.right)
    dfs(root)
    return ",".join(parts)

def deserialize(data):
    tokens = iter(data.split(","))
    def build():
        val = next(tokens)
        if val == "#":
            return None
        node = Node(int(val))
        node.left = build()
        node.right = build()
        return node
    return build()

root = Node(1)
root.left, root.right = Node(2), Node(3)
root.right.left, root.right.right = Node(4), Node(5)
s = serialize(root)
print(s)
print(serialize(deserialize(s)) == s)
